import{_ as l,a0 as s,w as p,s as u,ao as o,I as r,x as n,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"五种方法检测你的 Linux 是32位还是64位 | LCTT x X-CMD","titleTemplate":false,"description":"五种方法检测你的 Linux 是32位还是64位 | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"五种方法检测你的 Linux 是32位还是64位 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"五种方法检测你的 Linux 是32位还是64位 | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/5 Ways To Check If Linux OS is 32 bit or 64 Bit","title":"五种方法检测你的 Linux 是32位还是64位","tag":"201405","desc":""},"relativePath":"201405/5 Ways To Check If Linux OS is 32 bit or 64 Bit.md","filePath":"[post].md"}'),d={name:"201405/5 Ways To Check If Linux OS is 32 bit or 64 Bit.md"};function m(x,t,b,f,h,_){const a=s("Link");return p(),u("div",null,[t[14]||(t[14]=o('<h1 id="五种方法检测你的-linux-是32位还是64位" tabindex="-1">五种方法检测你的 Linux 是32位还是64位 <a class="header-anchor" href="#五种方法检测你的-linux-是32位还是64位" aria-label="Permalink to “五种方法检测你的 Linux 是32位还是64位”">​</a></h1><p>有的时候 Linux 新手们在下载软件的时候十分困惑，因为下载页面常常同时提供32位和64位版本的软件。所以弄清楚你的操作系统是32位的还是64位的十分重要，因为你在做很多事情的时候都需要这个信息。在这篇文章里，我们会讨论五种检测你的Linux系统是32位还是64位的方法。</p><h3 id="检测你的-linux-是32位还是64位的" tabindex="-1">检测你的 Linux 是32位还是64位的 <a class="header-anchor" href="#检测你的-linux-是32位还是64位的" aria-label="Permalink to “检测你的 Linux 是32位还是64位的”">​</a></h3><p>请注意文中的这些方法是在 Ubuntu 13.10 平台测试.</p><h4 id="_1-执行-uname-a-命令" tabindex="-1">1. 执行‘uname -a’ 命令 <a class="header-anchor" href="#_1-执行-uname-a-命令" aria-label="Permalink to “1. 执行‘uname -a’ 命令”">​</a></h4>',5)),r("p",null,[t[1]||(t[1]=n("最常见的一个测试方法是运行 ",-1)),e(a,{href:"http://mylinuxbook.com/linux-uname-command/"},{default:i(()=>[...t[0]||(t[0]=[n("uname command",-1)])]),_:1}),t[2]||(t[2]=n(" 命令。",-1))]),t[15]||(t[15]=o(`<p>例如，在我的系统里，它显示了以下信息：</p><pre><code>$ uname -a
 Linux ubuntu 3.11.0-12-generic #19-Ubuntu SMP Wed Oct 9 16:12:00 UTC 2013 i686 athlon i686 GNU/Linux
</code></pre><p>那个高亮的 <strong>i686</strong> (or 有时候会是i386) 说明操作系统是32位的，但是如果显示的是 <strong>x86_64</strong>，那就说明这个操作系统是64位的。</p><h4 id="_2-运行-uname-m-命令" tabindex="-1">2.运行 ‘uname -m’ 命令 <a class="header-anchor" href="#_2-运行-uname-m-命令" aria-label="Permalink to “2.运行 ‘uname -m’ 命令”">​</a></h4><p>上面的命令内涵太多了，可以用这个参数直指人心：‘uname -m’ 。</p><p>例如，在我的系统里，它显示了以下信息：</p><pre><code>$ uname -m
 i686
</code></pre><p>这说明我的 Ubuntu Linux 系统是32位的，如果输出显示的是x86_64，就说明系统是64位的。</p><h4 id="_3-使用-file-命令" tabindex="-1">3.使用 file 命令#### <a class="header-anchor" href="#_3-使用-file-命令" aria-label="Permalink to “3.使用 file 命令####”">​</a></h4><p>尽管这样做纯粹是炫耀技巧，但是仍然不失为一种达到目的的方法。使用这个方法，需要你运行 file 命令并带上 <strong>/sbin/init</strong> 作为参数。</p><p>举个例子:</p><pre><code>$ file /sbin/init
 /sbin/init: ELF 32-bit LSB shared object, Intel 80386, version 1 (SYSV), dynamically linked (uses shared libs), for GNU/Linux 2.6.24, BuildID[sha1]=0xc0d86a25a7abb14cad4a65a1f7d03605bcbd41f6, stripped
</code></pre><p>高亮的 <strong>32-bit</strong> 说明这是一个32位的操作系统,如果显示为 <strong>64-bit</strong> 则说明操作系统是64位的</p><h4 id="_4-使用-arch-命令" tabindex="-1">4. 使用 arch 命令 <a class="header-anchor" href="#_4-使用-arch-命令" aria-label="Permalink to “4. 使用 arch 命令”">​</a></h4><p>另外一个可以选择的方法是使用 arch 命令，这个命令用于输出机器的硬件名称。</p><p>这里有一个示例:</p><pre><code>$ arch
 i686
</code></pre><p>在这里你可以看到输出的是 i686, 这说明这是一个32位操作系统，对于64位的操作系统，输出的应该是x86_64。</p><h4 id="_5-通过系统设置的方法" tabindex="-1">5. 通过系统设置的方法 <a class="header-anchor" href="#_5-通过系统设置的方法" aria-label="Permalink to “5. 通过系统设置的方法”">​</a></h4><p>如果你使用的是 Ubuntu 12.04 或更高, 你可以很简单地在** All Settings -&gt; Details**里查看你的系统结构。</p><p><img src="http://mylinuxbook.com/wp-content/uploads/2014/04/details.png" alt="details"></p><p>这样你就可以看到系统类型(32-bit)在这里清晰地显示出来。</p><p>你还知道别的方法来检测操作系统是32位还是64位的吗？在下面回复与我们分享吧。</p><hr>`,24)),r("p",null,[t[4]||(t[4]=n("via: ",-1)),e(a,{href:"http://mylinuxbook.com/5-ways-to-check-if-linux-is-32-bit-or-64-bit/"},{default:i(()=>[...t[3]||(t[3]=[n("http://mylinuxbook.com/5-ways-to-check-if-linux-is-32-bit-or-64-bit/",-1)])]),_:1})]),r("p",null,[t[7]||(t[7]=n("译者：",-1)),e(a,{href:"https://github.com/crowner"},{default:i(()=>[...t[5]||(t[5]=[n("crowner",-1)])]),_:1}),t[8]||(t[8]=n(" 校对：",-1)),e(a,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...t[6]||(t[6]=[n("Caroline",-1)])]),_:1})]),r("p",null,[t[11]||(t[11]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[9]||(t[9]=[n("LCTT",-1)])]),_:1}),t[12]||(t[12]=n(" 原创翻译，",-1)),e(a,{href:"http://linux.cn/"},{default:i(()=>[...t[10]||(t[10]=[n("Linux中国",-1)])]),_:1}),t[13]||(t[13]=n(" 荣誉推出",-1))])])}const g=l(d,[["render",m]]);export{C as __pageData,g as default};
